'use strict';

const { expect }                            = require('chai');
const { createDriver, tapByText, tapById,
        isTextVisible, waitForText, fillCredentials,
        scrollDown, scrollUp, pressBack, loginAs,
        logout, screenshot, TIMEOUTS: T }  = require('../helpers/driver');
const { CREDENTIALS: CREDS }               = require('../config/appium.config');
const ExcelJS                               = require('exceljs');
const sfspath                               = require('path');
const sfsfs                                 = require('fs');

// ─── Results store ─────────────────────────────────────────────────────────
const TR = []; let SEQ = 0;
function log(suite, tcId, title, status, notes) {
  TR.push({ id: ++SEQ, tcId, suite, title, status, notes: notes || '', ts: new Date().toISOString() });
}

// ─── Test factory ───────────────────────────────────────────────────────────
function mk(suite, failMode) {
  return function (id, name, fn) {
    it(id + ': ' + name, async function () {
      const driver = this._driver;
      if (!driver) { log(suite, id, id + ': ' + name, 'SKIP', 'No driver'); this.skip(); return; }
      try {
        await fn(driver);
        log(suite, id, id + ': ' + name, 'PASS', 'OK');
      } catch (e) {
        if (failMode === 'SKIP') {
          log(suite, id, id + ': ' + name, 'SKIP', e.message.slice(0, 120));
          this.skip();
        } else {
          log(suite, id, id + ': ' + name, 'FAIL', e.message.slice(0, 120));
          try { await screenshot(driver, id); } catch (_) {}
          throw e;
        }
      }
    });
  };
}

// ─── Global after hook: Generate Excel Report ───────────────────────────────
after(async function () {
  this.timeout(60000);
  const passed  = TR.filter(r => r.status === "PASS").length;
  const failed  = TR.filter(r => r.status === "FAIL").length;
  const skipped = TR.filter(r => r.status === "SKIP").length;
  const total   = TR.length;
  const rate    = total > 0 ? ((passed / total) * 100).toFixed(1) : "0.0";

  const wb  = new ExcelJS.Workbook();
  wb.creator  = "SmartMed QA";
  wb.created  = new Date();

  const hFill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0D3B6E" } };
  const hFont = { bold: true, color: { argb: "FFFFFFFF" }, size: 11, name: "Calibri" };
  const ctr   = { horizontal: "center", vertical: "middle" };

  // Sheet 1 ─ Executive Summary
  const ss = wb.addWorksheet("Test Summary");
  ss.mergeCells("A1:H1");
  ss.getCell("A1").value     = "SmartMed Mobile App — Appium E2E Test Report";
  ss.getCell("A1").font      = { bold: true, size: 20, color: { argb: "FF0D3B6E" }, name: "Calibri" };
  ss.getCell("A1").alignment = ctr;
  ss.getRow(1).height = 48;

  ss.mergeCells("A2:H2");
  ss.getCell("A2").value     = "Generated: " + new Date().toLocaleString() +
    " | Framework: Appium 2.x + WebdriverIO + Mocha + Chai | Platform: Android/iOS";
  ss.getCell("A2").font      = { italic: true, color: { argb: "FF555555" }, size: 10 };
  ss.getCell("A2").alignment = ctr;
  ss.getRow(2).height = 20;
  ss.addRow([]);

  const metrics = [
    ["Metric", "Value", "", "Metric", "Value"],
    ["Total Test Cases", total,  "", "Pass Rate", rate + "%"],
    ["Passed",          passed,  "", "Platform",  "Android / iOS"],
    ["Failed",          failed,  "", "Framework", "Appium 2.x"],
    ["Skipped",         skipped, "", "Runner",    "Mocha + Chai"],
    ["App",             "SmartMed Medicate", "", "Type", "Mobile E2E"],
  ];
  metrics.forEach((row, i) => {
    const r = ss.addRow(row);
    if (i === 0) { [1,2,4,5].forEach(c => { r.getCell(c).fill = hFill; r.getCell(c).font = hFont; r.getCell(c).alignment = ctr; }); }
    r.height = 24;
  });
  ss.addRow([]);

  const suites = [...new Set(TR.map(r => r.suite))];
  const sh = ss.addRow(["Test Suite", "Total", "Passed", "Failed", "Skipped", "Pass Rate", "Health", "Role"]);
  sh.eachCell(c => { c.fill = hFill; c.font = hFont; c.alignment = ctr; });
  sh.height = 28;

  suites.forEach((s, i) => {
    const sr   = TR.filter(r => r.suite === s);
    const sp   = sr.filter(r => r.status === "PASS").length;
    const sf   = sr.filter(r => r.status === "FAIL").length;
    const sk   = sr.filter(r => r.status === "SKIP").length;
    const pr   = ((sp / sr.length) * 100).toFixed(0);
    const h    = sf === 0 && sk === 0 ? "✅ Healthy" : sf === 0 ? "⚠️ Partial" : "❌ Review";
    const row  = ss.addRow([s, sr.length, sp, sf, sk, pr + "%", h, ""]);
    const hCol = sf === 0 && sk === 0 ? "FFD1FAE5" : sf === 0 ? "FFFFF3CD" : "FFFEE2E2";
    row.getCell(7).fill = { type: "pattern", pattern: "solid", fgColor: { argb: hCol } };
    row.eachCell(c => { c.alignment = ctr; c.fill = c.fill || { type:"pattern",pattern:"solid",fgColor:{argb:i%2===0?"FFF0F5FF":"FFFFFFFF"} }; });
    row.height = 20;
  });

  ["A","B","C","D","E","F","G","H"].forEach((c, i) =>
    ss.getColumn(c).width = [44, 10, 10, 10, 10, 12, 14, 12][i]);

  // Sheet 2 ─ All Test Cases
  const ds = wb.addWorksheet("All Test Cases", { views: [{ state: "frozen", ySplit: 1 }] });
  ds.columns = [
    { header: "#",         key: "id",     width: 6  },
    { header: "TC ID",     key: "tcId",   width: 16 },
    { header: "Suite",     key: "suite",  width: 34 },
    { header: "Title",     key: "title",  width: 62 },
    { header: "Status",    key: "status", width: 10 },
    { header: "Notes",     key: "notes",  width: 55 },
    { header: "Timestamp", key: "ts",     width: 24 },
  ];
  ds.getRow(1).eachCell(c => { c.fill = hFill; c.font = hFont; c.alignment = ctr; });
  ds.getRow(1).height = 28;

  TR.forEach(r => {
    const row = ds.addRow(r);
    const sc  = row.getCell("status");
    if (r.status === "PASS") {
      sc.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFD1FAE5" } };
      sc.font = { color: { argb: "FF065F46" }, bold: true };
    } else if (r.status === "FAIL") {
      sc.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFEE2E2" } };
      sc.font = { color: { argb: "FF7F1D1D" }, bold: true };
    } else {
      sc.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFF3CD" } };
      sc.font = { color: { argb: "FF92400E" }, bold: true };
    }
    sc.alignment = ctr;
    row.height = 18;
  });
  ds.autoFilter = { from: "A1", to: "G1" };

  // Sheet 3 ─ Failed Tests
  const ft = TR.filter(r => r.status === "FAIL");
  if (ft.length > 0) {
    const fs2 = wb.addWorksheet("Failed Tests", { properties: { tabColor: { argb: "FFDC2626" } } });
    fs2.columns = [
      { header: "TC ID",  key: "tcId",  width: 16 },
      { header: "Suite",  key: "suite", width: 32 },
      { header: "Title",  key: "title", width: 60 },
      { header: "Notes",  key: "notes", width: 55 },
      { header: "Timestamp", key: "ts", width: 24 },
    ];
    const fh = fs2.getRow(1);
    fh.eachCell(c => { c.fill = { type:"pattern",pattern:"solid",fgColor:{argb:"FF922B21"} }; c.font = hFont; c.alignment = ctr; });
    fh.height = 26;
    ft.forEach(r => { fs2.addRow(r).height = 28; });
  }

  // Sheet 4 ─ Suite Breakdown
  const sb = wb.addWorksheet("Suite Breakdown");
  sb.columns = [
    { header: "Suite",   key: "suite",  width: 44 },
    { header: "Total",   key: "total",  width: 10 },
    { header: "Passed",  key: "pass",   width: 10 },
    { header: "Failed",  key: "fail",   width: 10 },
    { header: "Skipped", key: "skip",   width: 10 },
    { header: "Rate",    key: "rate",   width: 12 },
    { header: "Health",  key: "health", width: 16 },
  ];
  sb.getRow(1).eachCell(c => { c.fill = hFill; c.font = hFont; c.alignment = ctr; });
  sb.getRow(1).height = 28;
  suites.forEach((s, i) => {
    const sr   = TR.filter(r => r.suite === s);
    const sp   = sr.filter(r => r.status === "PASS").length;
    const sf   = sr.filter(r => r.status === "FAIL").length;
    const sk   = sr.filter(r => r.status === "SKIP").length;
    const rate = ((sp / sr.length) * 100).toFixed(1);
    const h    = sf === 0 && sk === 0 ? "✅ Healthy" : sf === 0 ? "⚠️ Partial" : "❌ Review";
    const row  = sb.addRow({ suite: s, total: sr.length, pass: sp, fail: sf, skip: sk, rate: rate + "%", health: h });
    row.eachCell(c => { c.alignment = ctr; });
    row.height = 22;
  });

  // Write file
  const outDir  = sfspath.join(__dirname, "..", "reports");
  if (!sfsfs.existsSync(outDir)) sfsfs.mkdirSync(outDir, { recursive: true });
  const outFile = sfspath.join(outDir,
    "SmartMed_Appium_E2E_Report_" + new Date().toISOString().slice(0, 10) + ".xlsx");
  await wb.xlsx.writeFile(outFile);

  console.log("\n════════════════════════════════════════════════════");
  console.log("  📊 SMARTMED APPIUM E2E REPORT GENERATED");
  console.log("════════════════════════════════════════════════════");
  console.log("  Total:  ", total);
  console.log("  ✅ Pass: ", passed);
  console.log("  ❌ Fail: ", failed);
  console.log("  ⏭  Skip: ", skipped);
  console.log("  📈 Rate: ", rate + "%");
  console.log("  📁 File: ", outFile);
  console.log("════════════════════════════════════════════════════\n");
});

